import {detailBoxes} from './detail-instances.js?v=48.0.0';
import {updateStudioStudy} from './studio-details.js?v=67.0.0';
export function buildLuggageStock(w,p,r,style){const cx=r.x+r.width/2,cz=r.y+r.height/2,wood=style.fixture,parts=[],box=(...a)=>parts.push(a);box(cx,2,cz,r.width-2,4,r.height-2,wood);box(cx,4.3,cz,r.width-4,.6,r.height-4,'#d7d7c5');const points=r.kind==='wall'?[cz]:[cz-r.height*.27,cz+r.height*.27];for(const z of points){const model=w.photo(p,cx,13.925,z,14,19.25);if(r.kind==='wall')model.rotation.y=r.side<0?Math.PI/2:-Math.PI/2;box(cx,4.9,z+11,Math.min(20,r.width-8),.6,6,'#f0e7d4');for(let j=0;j<3;j++)box(cx-5+j*5,5.3,z+11,.4,.2,3,style.accent);}detailBoxes(w,w.scene,parts);}
// Original travel gallery: measurement notes and neutral creative lining samples, not airline sizers.
export function buildLuggageStudio(w,st,style){const r=w.layout.rail,x=r.x+r.width/2,z=r.y+r.height/2,parts=[],box=(...a)=>parts.push(a),paper='#ede3cd',ink='#45635e';box(x,18,z,r.width-8,36,r.height-8,style.fixture);box(x,37,z,r.width-4,2,r.height-4,ink);box(x-55,39,z,62,2,34,paper);w.photo(st.products[0],x-55,49.625,z,14,19.25);for(let j=0;j<6;j++)box(x+36+j*6,39,z,.4,.5,r.height-16,paper);box(x+54,39,z,41,.5,1,paper);for(const dx of[-r.width*.3,r.width*.3]){box(x+dx,16,z+r.height/2-5,r.width*.4,25,1,ink);box(x+dx,26,z+r.height/2-4,22,1,1,paper);}const samples=[];for(const[i,xx]of[563,600,637].entries()){box(xx,33,149,29,2,25,ink);const mat=w.mat(['#c5b08a','#9da99f','#667b79'][i],{roughness:.9});w.box(xx,35,149,24,2,20,mat);samples.push(mat);box(xx,36.3,156,18,.4,4,paper);}box(630,17,630,22,1,15,paper);for(let j=0;j<4;j++)box(623+j*4,17.7,630,.4,.2,10,ink);detailBoxes(w,w.scene,parts);w.studioStudy={store:st.id,samples,signature:null,group:'textile'};updateStudioStudy(w);w.canvas.dataset.luggageStudio='63';}
